#!/usr/bin/env bash
# Scenario C - credential misuse / anomalous login pattern (Stage 2 §9 Scenario C).
#
# IMPORTANT: AWS CloudTrail's ConsoleLogin event is generated by the actual browser-based sign-in
# flow, not by any CLI call - there is no clean, ToS-respecting way to script repeated console
# password attempts. Steps 1-4 (three failed logins, one successful) are therefore MANUAL: this
# script prints instructions and waits for you to press Enter after each attempt (aws/lib/gt_logger.sh
# log_step_prompt), recording the wall-clock time at that moment. Only step 5 (RunInstances) is scripted.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HERE/../lib/common.sh" "$@"
require_preflight; require_cost_ack
GT_SCENARIO=scenario_c
source "$HERE/../lib/gt_logger.sh"

ACCT=$(account_id)
BOB_ARN="arn:aws:iam::${ACCT}:user/analyst-bob"
BOB_PW_FILE="$SCRATCH_DIR/analyst_bob_console_password.txt"
BOB_KEY_FILE="$SCRATCH_DIR/analyst_bob_access_key.json"
BOB_PROFILE="cffc-bob-temp"
INSTANCE_ID_FILE="$SCRATCH_DIR/scenario_c_instance_id.txt"

cleanup() {
  if [ -f "$BOB_KEY_FILE" ] && [ "$DRY_RUN" != "1" ]; then
    local akid; akid=$(python3 -c "import json;print(json.load(open('$BOB_KEY_FILE'))['AccessKey']['AccessKeyId'])" 2>/dev/null || true)
    [ -n "$akid" ] && { echo "-- Deleting short-lived access key for analyst-bob ($akid) --"; awscli iam delete-access-key --user-name analyst-bob --access-key-id "$akid" || true; }
    shred -u "$BOB_KEY_FILE" 2>/dev/null || rm -f "$BOB_KEY_FILE"
  fi
  if [ -f "$INSTANCE_ID_FILE" ] && [ "$DRY_RUN" != "1" ]; then
    local iid; iid=$(cat "$INSTANCE_ID_FILE")
    echo "-- Terminating scenario instance $iid --"
    awscli ec2 terminate-instances --instance-ids "$iid" >/dev/null || true
    rm -f "$INSTANCE_ID_FILE"
  fi
}
trap cleanup EXIT

echo "== Scenario C: credential misuse / anomalous login pattern =="
confirm "PROCEED" "This requires YOU to manually attempt console sign-in as analyst-bob (3 wrong, 1 correct password), then scripts one real EC2 RunInstances call (terminated automatically at the end of this script)."

echo
echo ">>> MANUAL PREP: find the console sign-in URL and analyst-bob's password:"
echo ">>>   Sign-in URL: https://${ACCT}.signin.aws.amazon.com/console"
if [ -f "$BOB_PW_FILE" ]; then
  echo ">>>   Password file (read it yourself, it is not printed here): $BOB_PW_FILE"
else
  echo ">>>   WARNING: $BOB_PW_FILE not found - did setup/04_least_privilege_iam.sh create analyst-bob's login profile?" >&2
fi
echo

log_step_prompt "ConsoleLogin" "$BOB_ARN" "NULL" "NULL" "group_1" "true" "credential_access" \
  "sign in as analyst-bob with a DELIBERATELY WRONG password (attempt 1 of 3)"
log_step_prompt "ConsoleLogin" "$BOB_ARN" "NULL" "NULL" "group_1" "true" "credential_access" \
  "wrong password, attempt 2 of 3"
log_step_prompt "ConsoleLogin" "$BOB_ARN" "NULL" "NULL" "group_1" "true" "credential_access" \
  "wrong password, attempt 3 of 3"
log_step_prompt "ConsoleLogin" "$BOB_ARN" "NULL" "NULL" "group_1" "true" "initial_access" \
  "now sign in with the CORRECT password from $BOB_PW_FILE - AWS will likely require you to set a new password (password-reset-required was set at creation)"

echo "-- Step 5: RunInstances AS analyst-bob (scripted; instance auto-terminated at end of this script) --"
if [ "$DRY_RUN" != "1" ]; then
  awscli iam create-access-key --user-name analyst-bob --output json > "$BOB_KEY_FILE"
  AKID=$(python3 -c "import json;print(json.load(open('$BOB_KEY_FILE'))['AccessKey']['AccessKeyId'])")
  ASEC=$(python3 -c "import json;print(json.load(open('$BOB_KEY_FILE'))['AccessKey']['SecretAccessKey'])")
  aws configure set aws_access_key_id "$AKID" --profile "$BOB_PROFILE"
  aws configure set aws_secret_access_key "$ASEC" --profile "$BOB_PROFILE"
  aws configure set region "$AWS_REGION" --profile "$BOB_PROFILE"
  unset ASEC
  echo "   temp profile '$BOB_PROFILE' configured (key id only: ${AKID:0:4}********); waiting 10s for propagation"
  sleep 10

  AMI=$(awscli_read ssm get-parameter --name /aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64 --query Parameter.Value --output text)
  SUBNET=$(awscli_read ec2 describe-subnets --filters Name=default-for-az,Values=true --query 'Subnets[0].SubnetId' --output text)
  echo "   AMI=$AMI  Subnet=$SUBNET  InstanceType=t3.micro (free-tier eligible; see docs/COST_NOTES.md)"
  RUN_OUT=$(aws --profile "$BOB_PROFILE" --region "$AWS_REGION" ec2 run-instances \
    --image-id "$AMI" --instance-type t3.micro --subnet-id "$SUBNET" --count 1 \
    --tag-specifications "ResourceType=instance,Tags=[{Key=Project,Value=$PROJECT_TAG},{Key=Name,Value=cffc-scenario-c}]" \
    --output json)
  IID=$(echo "$RUN_OUT" | python3 -c 'import json,sys;print(json.load(sys.stdin)["Instances"][0]["InstanceId"])')
  echo "$IID" > "$INSTANCE_ID_FILE"
  echo "   launched $IID - will be terminated automatically when this script exits (including on error)."
else
  echo "[dry-run] would create an access key for analyst-bob, run-instances t3.micro, then terminate it"
fi
log_step "RunInstances" "$BOB_ARN" "NULL" "${IID:-NULL}" "group_1" "true" "execution" "launched by analyst-bob after successful login; auto-terminated at script exit"

echo "-- Finalizing and freezing ground truth --"
python3 "$HERE/../lib/gt_finalize.py" --scenario scenario_c --jsonl "$GT_SCRATCH" \
  --groups '[{"group_id":"group_1","rationale":"same principal (analyst-bob) across failed/successful logins and RunInstances"}]' \
  --out "$REPO_ROOT/data/real/ground_truth/scenario_c_ground_truth.json" --author "${USER:-researcher}"

echo
echo "Scenario C script complete (instance termination + key deletion run now via trap)."
echo "Next: aws/collection/05_export_evidence.sh scenario_c"
echo "[VERIFY AT RUNTIME] Confirm in the EC2 console that no instance tagged Project=$PROJECT_TAG is left running."
